// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.system.handlerimport timber.log.Timberimport com.roshan.persona.brain.skill.SystemOperationimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport com.roshan.persona.system.executor.ResourceCategoryimport com.roshan.persona.system.util.HardwareExceptionMapper/** * NOUS — Alarm Handler (Module 10 v2 — Step 10.8). * * Sets alarms via Android's `AlarmClock.ACTION_SET_ALARM` intent. * * ## Behavior (per strategy §"Time / Alarms") * *  - Launches the system clock app's "set alarm" UI pre-filled with *    hour/minute/label/repeat-days. *  - Requires no special permission — any app can fire the AlarmClock intent. *  - The user confirms the alarm in the clock app (Android design — apps *    can't silently set alarms without user confirmation). * * ## Exception handling (Review 2 Fix C) * *  - `ActivityNotFoundException` (no clock app installed) → mapped to *    `Hardware.Unsupported` with message "No clock app installed". * * ## Reversibility * * Not reversible — Android's `AlarmClock` intent API has no * `ACTION_CANCEL_ALARM`. The clock app owns the alarm, so cancellation * requires the user to dismiss it manually in the clock app. * * The [cancel] method opens the alarm list (`AlarmClock.ACTION_SHOW_ALARMS`) * so the user can find + dismiss the alarm they just set. This is the * best-effort inverse — a true programmatic cancel would require NOUS to * schedule alarms itself via `AlarmManager.setExact` against its own * `PendingIntent`, which the strategy doc rules out (Android 12+ requires * `SCHEDULE_EXACT_ALARM` permission + user grant for exact alarms). * * ## Resource category * * Alarms use [ResourceCategory.APP] — fires an intent that launches an app. * * @see <a href="docs/strategy/module-10-system-strategy-v2.md">§Scope — Alarms</a> */class AlarmHandler(    private val alarmClockService: AlarmClockService,) : StatelessSystemOperationHandler<SystemOperation.SetAlarm>() {    override val id: String = "alarm"    override val displayName: String = "Alarm Setter"    override val requiredPermissions: Set<String> = setOf(        "com.android.alarm.permission.SET_ALARM",    )    override val resourceCategory: ResourceCategory = ResourceCategory.APP    override fun isAvailable(): Boolean = true  // most devices have a clock app    override suspend fun execute(operation: SystemOperation.SetAlarm): Result<Unit> {        // Validate hour + minute.        if (operation.hour !in 0..23) {            return Result.Failure(                error = AppError.Hardware.Unsupported(                    resource = "alarm:hour:${operation.hour}",                    cause = null,                ),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        }        if (operation.minute !in 0..59) {            return Result.Failure(                error = AppError.Hardware.Unsupported(                    resource = "alarm:minute:${operation.minute}",                    cause = null,                ),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        }        return HardwareExceptionMapper.withMappingSync("alarm") {            // SetAlarm currently has no daysOfWeek field — pass empty (one-time).            // Future: extend SystemOperation.SetAlarm with repeat-days.            val success = alarmClockService.setAlarm(                hour = operation.hour,                minute = operation.minute,                label = operation.label,                daysOfWeek = IntArray(0),            )            if (success) {                Result.Success(Unit, CorrelationId.generate(), 0)            } else {                Result.Failure(                    error = AppError.Hardware.Unsupported("alarm_app"),                    correlationId = CorrelationId.generate(),                    durationNanos = 0,                )            }        }    }    /**     * Best-effort cancel — opens the system alarm list UI so the user can     * manually dismiss the alarm they just set.     *     * Android's `AlarmClock` intent API has no `ACTION_CANCEL_ALARM`, so a     * true programmatic cancel is not possible without NOUS scheduling the     * alarm itself via `AlarmManager.setExact` (requires     * `SCHEDULE_EXACT_ALARM` permission + Android 12+ user grant — strategy     * §"Privacy & Security" rules this out). See class KDoc.     *     * @return `true` if the alarm list UI was launched successfully.     */    suspend fun cancel(): Boolean {        return try {            alarmClockService.showAlarms()        } catch (t: Throwable) {            Timber.tag("AlarmHandler").w(t, "cancel failed — could not open alarm list")            false        }    }}
